<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$user=api_user();api_rate_limit($user,'hunts.scan',setting_int('hunt_scan_rate_per_minute',10),60);$data=json_input();$token=trim((string)($data['qr_token']??''));if(!preg_match('/^[a-f0-9]{64}$/i',$token)||!is_numeric($data['latitude']??null)||!is_numeric($data['longitude']??null))json_response(false,'QR token and GPS coordinates are required',null,422);try{$result=validate_hunt_scan($user,$token,(float)$data['latitude'],(float)$data['longitude'],isset($data['accuracy_meters'])?(float)$data['accuracy_meters']:null,['mock_location'=>filter_var($data['mock_location']??false,FILTER_VALIDATE_BOOL)]);json_response(true,'QR and GPS validated',$result,201);}catch(InvalidArgumentException $e){json_response(false,$e->getMessage(),null,422);}catch(RuntimeException $e){json_response(false,$e->getMessage(),null,409);}
